// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    address owner = address(0xABCD);

    function setUp() public {
        c = new DepositLog();
    }

    function testFuzz_property(address logger, bool status) public {

        vm.prank(address(0));
        bool ok;
        try c.setApprovedLogger(logger, status) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || c.approvedLoggers(logger) == status);
    }
}
